// Turns the fetched website into a short text sample and joins it to the lead.
// Nothing here calls a model; it only prepares what the model will read.
const lead = $('Normalise the lead').first().json;
const page = $input.first().json;
const html = typeof page.data === 'string' ? page.data : '';

const strip = (h) => h
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&[a-z#0-9]+;/gi, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const title = strip((html.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1] || '');
const description = ((html.match(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']/i) || [])[1] || '').trim();
const text = strip(html).slice(0, 3000);
const freeMail = /@(gmail|googlemail|yahoo|hotmail|outlook|live|msn|icloud|me|aol|proton|protonmail|gmx|yandex)\./i.test(lead.email || '');

return [{ json: {
  ...lead,
  freeMail,
  pageFetched: html.length > 0,
  pageTitle: title,
  pageDescription: description,
  pageText: text
} }];

