// Reads the model's JSON, decides the tier with your thresholds, and refuses
// to guess: anything that is not a clean score goes to a person as "review".
const res = $input.first().json;
const lead = $('Prepare the brief').first().json;
const settings = $('Settings').first().json;

let out = {
  score: -1,
  tier: 'review',
  summary: 'The model declined or returned no usable score. A person should read this lead.',
  fit_reasons: [],
  concerns: [],
  recommended_next_step: 'Read the original message and decide by hand.'
};

if (res && res.stop_reason !== 'refusal' && Array.isArray(res.content)) {
  const block = res.content.find((b) => b.type === 'text');
  try {
    const parsed = JSON.parse(block.text);
    if (Number.isInteger(parsed.score)) out = { ...out, ...parsed };
  } catch (e) {
    // leave the review defaults in place
  }
}

if (out.score >= 0) {
  out.tier = out.score >= Number(settings.hotThreshold) ? 'hot'
    : out.score >= Number(settings.warmThreshold) ? 'warm' : 'cold';
}

return [{ json: {
  ...lead,
  ...out,
  model: res && res.model ? res.model : null,
  scoredAt: new Date().toISOString()
} }];

